  function L(fr) { if (lang === "fr" || fr == null) return fr; var e = D[fr]; return e ? e[lang === "en" ? 0 : 1] : fr; }
  /* Static page text: translate text nodes and a few attributes whose whole trimmed value is in the list */
  function tr(root) {
    if (lang === "fr") return;
    var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null), n, list = [];
    while ((n = w.nextNode())) list.push(n);
    list.forEach(function (t) {
      var p = t.parentNode; if (!p || /^(SCRIPT|STYLE|TEXTAREA|CODE)$/.test(p.nodeName)) return;
      var raw = t.nodeValue, key = raw.trim(); if (!key || !D[key]) return;
      t.nodeValue = raw.replace(key, L(key));
    });
    root.querySelectorAll("[placeholder],[aria-label],[title]").forEach(function (e) {
      ["placeholder", "aria-label", "title"].forEach(function (a) { var v = e.getAttribute(a); if (v && D[v.trim()]) e.setAttribute(a, L(v.trim())); });
    });
  }
  return { lang: lang, loc: LOC[lang], L: L, tr: tr };
